RED.typeql = ( function(){

    var dialog;
    var dialogContainer;
    var exportTypeqlNodesDialog;
    var importTypewlNodesDialog;
    var activeTab;
    var libraryBrowser;
    var disabled = false;

    // DataStructures for TypeQl
    var typeql_schema_dict = {}
    var typeql = ""
    var attr_schema, entity_schema, rel_schema, rule_schema = ""
    var attr_map = {}
    var group_map = {}
    var subtype_map = {}
    var newline= "\n"

    // FUNCTIONS TO TRANSFORM NODES IN JSON TO TYPE QL
    function declareBaseTypeql()
    {
        attr_map = {}
        typeql = ""
        typeql = typeql+ '\n## Version : 1.0 Geminos NodeRed -> Grakn'
        typeql = typeql + '\n## Contact : Jeff Dalgliesh\n\n'
        typeql = typeql + 'define \n\n'
        typeql = typeql + '## Setup all attributes first, then we can use them in entities and relationships \n\n'
    
        attr_schema = "################## Attributes ##################"
        entity_schema = "##################  Entities  ##################"
        rel_schema = "##################### Relations #####################"
        rule_schema = "#####################     Rules     #####################"

  
        typeql_schema_dict = {
            "attribute": attr_schema,
            "entity": entity_schema,
            "relation": rel_schema,
            "rule": rule_schema,
        }
    }
    function add_to_map(prop)
    {
        // attr_map[prop["v"]] = ""
        attr_map[prop["v"]] = prop["vt"]
    }

    function add_rule(node){
        var type = node.type
        var subtype = node.type;
        var sub = false;

        var statement = newline + "\t" + type + " " + node["name"] + ": \n"
        typeql_schema_dict[type] += statement

        // add corresponding properties
        node.props.forEach( (prop) =>{
            if (prop.p =="when"){
                statement = "\t\t" +  prop["p"] + " {\n\t\t\t" + prop["v"] +";\n\t\t }"  
                typeql_schema_dict[type] += statement   
            }
            else{
                statement = prop["p"] + " {\n\t\t\t" + prop["v"] + ";\n\t\t }"  
                typeql_schema_dict[type] += statement     

            }
            if (prop["p"] == "owns"){
                add_to_map(prop)
            }
        })

        //  add semi colon
        typeql_schema_dict[type] += ";"


    }

    function add_node(node, index, array){
        var type = node.type
        if(type !== "tab"){
            
            if(type == "event"){
                type = "event"
            }

            // =================================================================
            // if(type == "group"){
            //     // grab class type of group to see if it is entity / relationship
            //     type = node["classtype"];
            
            //     nodename = node.name
            //     for (var i = 0; i < node.nodes.length; i++){
            //         n = node.nodes[i]
            //         group_map[n]= nodename
            //     }
            // }
            // else{
            //     // check if node id exists inside a group and update the subtype
            //     if(group_map[node.id])
            //     {
            //         sub = true;
            //         subtype = group_map[node.id]
            //     }
            // }
            // =================================================================

           
            if(type =="rule"){
                // console.log("Rule node : ", node)
                add_rule(node)
            }
            if(type === "entity" || type === "relation"){
                var statement = newline + "\t" + node["name"] + " sub "
                typeql_schema_dict[type] += statement

                var parent_type= subtype_map[node.id] ? subtype_map[node.id] : type
                typeql_schema_dict[type] += parent_type
                typeql_schema_dict[type] += ","

                if(node["abstract"]){
                    typeql_schema_dict[type] += " abstract,"
                }

                // add key to class
                if(typeof node.key !== typeof undefined )
                {
                    var prop = {
                        v:node.key,
                        vt: node.keytype
                    }
                    // console.log("Node key: " , node.key)
                    add_to_map(prop)
                    var statement = "\n\t\towns " + node.key + " @key,"
                    // console.log("Adding statement: ", statement)
                    typeql_schema_dict[type] += statement
                }

                // add corresponding properties
                if(node.props) {
                node.props.forEach( (prop) =>{
                    var statement = newline + "\t\t" + prop["p"] + " " + prop["v"] + ","
                    typeql_schema_dict[type] += statement
                    if (prop["p"] == "owns"){
                        add_to_map(prop)
                    }
                })
            
                // remove last comma added in props
                typeql_schema_dict[type] = typeql_schema_dict[type].slice(0,-1);
                //  add semi colon
                typeql_schema_dict[type] += ";"
            }
            }
        

        }
        
    }
    function add_attribute(attr_name){
        var statement = newline + "\t" + attr_name + " sub attribute," + newline + "\t\t value " + attr_map[attr_name] + ";"
        typeql_schema_dict["attribute"] += statement
    }


    var deploymnetTypes = {
        "import" : {img: "red/images/deploy-vaticle-o.png"},
        "export" : {img: "red/images/deploy-vaticle.png"}

    }

    var ignoreDeployWarnings = {
        unknown: false,
        unusedConfig:false,
        invalide: false,
    }

    var deploymentType = "export"


    function showTypeqlImportDialog(){
        return ""
    }

    function showTypeqlExportDialog()
    {
        dialogContainer.empty();
        dialogContainer.append($(exportTypeqlDialog));

        // reset the typeql being displayed
        declareBaseTypeql()


        var tabs = RED.tabs.create({
            id: "red-ui-typeql-dialog-export-tabs",
            vertical: true,
            onchange: function(tab) {
                $("#red-ui-typeql-dialog-export-tabs-content").children().hide();
                $("#" + tab.id).show();
                activeTab = tab.id;
                if (tab.id === "red-ui-typeql-dialog-export-tab-typeql") {
                    $("#red-ui-typeql-dialog-export").button("option","label", "Copy")
                    $("#red-ui-typeql-dialog-download").show();
                } else {
                    $("#red-ui-typeql-dialog-export").button("option","label", "Export")
                    $("#red-ui-typeql-dialog-download").hide();
                    libraryBrowser.focus();
                }

            }
        });
        tabs.addTab({
            id: "red-ui-typeql-dialog-export-tab-typeql",
            label: "Clipboard"
        });

        $("#red-ui-typeql-dialog-export").button("enable");


        dialogContainer.i18n();
        var format = RED.settings.flowFilePretty ? "red-ui-clipboard-dialog-export-fmt-full" : "red-ui-clipboard-dialog-export-fmt-mini";

        // GET NODES IN CURRENT WORKSPACE
        var nodes = null;
        // get active workspace
        var activeWorkspace = RED.workspaces.active()
        // console.log("Red active workspaces : ", activeWorkspace)
        // get groups in active workspace
        nodes = RED.nodes.groups(activeWorkspace);

        nodes = nodes.concat(RED.nodes.filterNodes({z:activeWorkspace}))
        // console.log("Filtered nodes: " , RED.nodes.filterNodes({z:activeWorkspace}))
        var parentNode = RED.nodes.workspace(activeWorkspace)||RED.nodes.subflow(activeWorkspace) || RED.nodes.submodel(activeWorkspace);
        nodes.unshift(parentNode);
        nodes = RED.nodes.createExportableNodeSet(nodes);

        // console.log("Exportable Nodes: " , nodes)

        activeLinks = RED.nodes.filterLinks({
            source:{z:activeWorkspace},
            target:{z:activeWorkspace}
        });

        activeLinks.forEach(link =>
        {
            if(link.source.type === link.target.type){
                // store the id of the node and assign it the name of the source 
                subtype_map[link.target.id] = link.source.name
                // console.log(link)
            }
        })
        // console.log("CLASS MAP: ", subtype_map)


        // CONVERT NODES TO TYPEQL
        // add nodes
        // console.log("filtering through nodes now: ")
        nodes.forEach((item, index, array)=> {
            add_node(item,index,array)
       })
        // add attribute typeql
        for(var attribute in attr_map){
            add_attribute(attribute)
        }

        // generate full typeql
        for( var type in typeql_schema_dict)
        {
            var statement = typeql_schema_dict[type] + newline +newline +newline
            typeql += statement
        }

        if(nodes !== null)
        {
            if (format === "red-ui-typeql-dialog-export-fmt-full"){
                flow = JSON.stringify(nodes,null, 4)
            }
            else
            {
                flow = JSON.stringify(nodes)
            }
        }

        // ADD JSOB OBJECT TO TEXT AREA
        if (flow.length > 0) {
            $("#red-ui-typeql-dialog-export").removeClass('disabled');
        } else {
            $("#red-ui-typeql-dialog-export").addClass('disabled');
        }
        $("#red-ui-typeql-dialog-export-text").val(typeql);
        setTimeout(function() { $("#red-ui-typeql-dialog-export-text").scrollTop(0); },50);
        $("#red-ui-typeql-dialog-export-text").trigger("focus");


        // prepare dialog window and make it adjustable
        var dialogHeight = 400;
        var winHeight = $(window).height();
        if (winHeight < 600) {
            dialogHeight = 400 - (600 - winHeight);
        }
        $(".red-ui-typeql-dialog-box").height(dialogHeight);

        // open dialog interface
        dialog.dialog("option","title", "Export TypeQL")
        .dialog("option","width",700)
        .dialog("open");
    }
 
    function setUpTypeqlDialogs()
    {
        dialog = $('<div id="red-ui-typeql-dialog" class="hide"><form class="dialog-form form-horizontal"></form></div>')
        .appendTo("#red-ui-editor")
        .dialog({
            modal: true,
            autoOpen: false,
            width: 700,
            resizable: false,
            classes: {
                "ui-dialog": "red-ui-editor-dialog",
                "ui-dialog-titlebar-close": "hide",
                "ui-widget-overlay": "red-ui-editor-dialog"
            },
            buttons: [
                { // red-ui-typeql-dialog-cancel
                    id: "red-ui-typeql-dialog-cancel",
                    text: "Cancel",
                    click: function() {
                        $( dialog ).dialog( "close" );
                    }
                },
                { // red-ui-typeql-dialog-download
                    id: "red-ui-typeql-dialog-download",
                    class: "primary",
                    text:"Download",
                    click: function() {
                        var element = document.createElement('a');
                        element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent($("#red-ui-typeql-dialog-export-text").val()));
                        element.setAttribute('download', "schema.tql");
                        element.style.display = 'none';
                        document.body.appendChild(element);
                        element.click();
                        document.body.removeChild(element);
                        $( this ).dialog( "close" );
                    }
                },
                { // red-ui-typeql-dialog-export
                    id: "red-ui-typeql-dialog-export",
                    class: "primary",
                    text: RED._("typeql.export.copy"),
                    click: function() {
                        if (activeTab === "red-ui-typeql-dialog-export-tab-typeql") {
                            $("#red-ui-typeql-dialog-export-text").select();
                            document.execCommand("copy");
                            document.getSelection().removeAllRanges();
                            RED.notify("Exported TypeQL",{id:"typeql"});
                            $( this ).dialog( "close" );
                        } else {
                            var flowToExport = $("#red-ui-typeql-dialog-export-text").val();
                            var selectedPath = libraryBrowser.getSelected();
                            if (!selectedPath.children) {
                                selectedPath = selectedPath.parent;
                            }
                            var filename = $("#red-ui-typeql-dialog-tab-library-name").val().trim();
                            var saveFlow = function() {
                                $.ajax({
                                    url:'library/'+selectedPath.library+'/'+selectedPath.type+'/'+selectedPath.path + filename,
                                    type: "POST",
                                    data: flowToExport,
                                    contentType: "application/json; charset=utf-8"
                                }).done(function() {
                                    $(dialog).dialog( "close" );
                                    RED.notify(RED._("library.exportedToLibrary"),"success");
                                }).fail(function(xhr,textStatus,err) {
                                    if (xhr.status === 401) {
                                        RED.notify(RED._("library.saveFailed",{message:RED._("user.notAuthorized")}),"error");
                                    } else {
                                        RED.notify(RED._("library.saveFailed",{message:xhr.responseText}),"error");
                                    }
                                });
                            }
                            if (selectedPath.children) {
                                var exists = false;
                                selectedPath.children.forEach(function(f) {
                                    if (f.label === filename) {
                                        exists = true;
                                    }
                                });
                                if (exists) {
                                    dialog.dialog("close");
                                    var notification = RED.notify(RED._("typeql.export.exists",{file:RED.utils.sanitize(filename)}),{
                                        type: "warning",
                                        fixed: true,
                                        buttons: [{
                                            text: RED._("common.label.cancel"),
                                            click: function() {
                                                notification.hideNotification()
                                                dialog.dialog( "open" );
                                            }
                                        },{
                                            text: RED._("typeql.export.overwrite"),
                                            click: function() {
                                                notification.hideNotification()
                                                saveFlow();
                                            }
                                        }]
                                    });
                                } else {
                                    saveFlow();
                                }
                            } else {
                                saveFlow();
                            }
                        }
                    }
                },

            ],
            open: function( event, ui ) {
                RED.keyboard.disable();
            },
            close: function(e) {
                RED.keyboard.enable();
            }
        });
        dialogContainer = dialog.children(".dialog-form");

        exportTypeqlDialog =
            '<div class="form-row">'+
                '<label style="width:auto;margin-right: 10px;">Export</label>'+
                '<span id="red-ui-typeql-dialog-export-rng-group" class="button-group">'+
                    '<a id="red-ui-typeql-dialog-export-rng-flow" class="red-ui-button toggle" href="#"> Current Flow </a>'+
                '</span>'+
            '</div>'+
            '<div class="red-ui-clipboard-dialog-box">'+
                '<div class="red-ui-clipboard-dialog-tabs">'+
                    '<ul id="red-ui-typeql-dialog-export-tabs"></ul>'+
                '</div>'+
                '<div id="red-ui-typeql-dialog-export-tabs-content" class="red-ui-clipboard-dialog-tabs-content">'+
                    '<div id="red-ui-typeql-dialog-export-tab-typeql" class="red-ui-clipboard-dialog-tab-clipboard">'+
                        '<div class="form-row" style="height:calc(100% - 30px)">'+
                            '<textarea readonly id="red-ui-typeql-dialog-export-text"></textarea>'+
                        '</div>'+
                        '<div class="form-row" style="text-align: right;">'+
                            '<span id="red-ui-typeql-dialog-export-fmt-group" class="button-group">'+
                                '<a id="red-ui-typeql-dialog-export-fmt-mini" class="red-ui-button red-ui-button-small toggle" href="#" data-i18n="clipboard.export.compact"></a>'+
                                '<a id="red-ui-typeql-dialog-export-fmt-full" class="red-ui-button red-ui-button-small toggle" href="#" data-i18n="clipboard.export.formatted"></a>'+
                            '</span>'+
                        '</div>'+
                    '</div>'+
                '</div>'
            '</div>'
            ;
    }

    function changeDeploymentType(type) {
        deploymentType = type;
        $('#red-ui-header-button-typeql-icon').attr("src", deploymnetTypes[type].img)
    }

    function init(options){

        setUpTypeqlDialogs();

        $('<li> <span class = "red-ui-deploy-button-group button-group" >'
        // create the section of the button to implement action 
            +'<a id="red-ui-header-button-typeql-action" class="red-ui-deploy-button disabled" href="#">'
                + '<span class="red-ui-deploy-button-content">' 
                + '<img id="red-ui-header-button-typeql-icon" src="red/images/deploy-vaticle-o.png">'
                +'<span> TypeQL </span>'
                + '</span>' 
            +'</a>'
            // create dropdown carret menu
            +'<a id="red-ui-header-button-typeql-options" class="red-ui-deploy-button" href="#"><i class="fa fa-caret-down"></i></a>'
        +'</span></li>').prependTo(".red-ui-header-toolbar");
        RED.menu.init({
            id:"red-ui-header-button-typeql-options",
            options:[
                {
                    id:"typeqlmenu-item-import", 
                    toggle:"typeql-type",
                    icon:"red/images/deploy-vaticle-o.png", 
                    label: "TypeQL Import", 
                    sublabel:"Import typeql schema as nodes", 
                    selected: true,
                    onselect:function(s) { if(s){changeDeploymentType("import")}}
                },               
                {
                    id:"typeqlmenu-item-export", 
                    toggle:"typeql-type",
                    icon:"red/images/deploy-vaticle-o.png", 
                    label: "TypeQL Export", 
                    sublabel:"Export current nodes to typeql schema", 
                    onselect: function(s) { if(s){changeDeploymentType("export")}},
                },
            ]
         });

         $('#red-ui-header-button-typeql-action').on("click", function(event){
             event.preventDefault();
             if(deploymentType == "export"){
                 showTypeqlExportDialog()
             }
             return          
         })


        //  RED.actions.add("core:typeql-actions",);
         RED.actions.add("core:set-typeql-to-import",function() { RED.menu.setSelected("typeql-item-import",true);});
         RED.actions.add("core:set-typeql-to-export",function() { RED.menu.setSelected("typeql-item-export",true); });

  

 
         
    };

    return {
        init: init
    };
})();